function collectDestinationStops(){const rows=$$('#tripDestinationStops .trip-destination-stop'),out=[];for(const row of rows){const country=canonicalCountry(row.querySelector('.trip-stop-country').value);if(!country)continue;const input=row.querySelector('.trip-destination-name'),typed=input.value.trim();let name='',type=row.querySelector('.trip-destination-type')?.value||'Other',custom=false;if(typed){const known=knownDestination(typed,country);name=known?.name||typed;type=known?.type||type;custom=!known;if(custom){const exists=(state.customDestinations||[]).some(d=>d.name.toLowerCase()===name.toLowerCase()&&sameCountry(d.country,country));if(!exists)state.customDestinations.push({id:`custom-${Date.now()}-${Math.random().toString(36).slice(2,7)}`,name,type,country})}}out.push({id:row.dataset.stopId||crypto.randomUUID?.()||String(Date.now()+out.length),name,type,country,start:row.querySelector('.trip-destination-from').value,end:row.querySelector('.trip-destination-to').value,travelMode:row.querySelector('.trip-travel-mode')?.value||'',custom})}return out}
