$('#tripForm').onsubmit=e=>{e.preventDefault();const stops=collectDestinationStops(),countries=[...new Set(stops.map(d=>d.country).filter(Boolean))];if(!countries.length){showWozzaAlert('Please choose a country for at least one stop.');return}let name=$('#tripName').value.trim();if(!name)name=countries.length===1?countries[0]:countries.join(' & ');const firstStop=stops[0]||{},lastStop=stops[stops.length-1]||firstStop,start=firstStop.start||'',end=(stops.length===1?firstStop.end:lastStop.end)||'';const companions=[...new Set($$('#tripCompanionBank .companion-tag.selected').map(b=>b.dataset.companion).filter(Boolean))];const existing=editingTripId?state.trips.find(x=>String(x.id)===String(editingTripId)):null,oldCountries=existing?tripCountries(existing).slice():[],t=existing||{id:crypto.randomUUID?.()||String(Date.now())};const tripStatus=existing?.status||'upcoming';Object.assign(t,{name,start,end,countries,destinations:stops,cities:{},companions,plan:existing?.plan||'',notes:$('#tripNotes').value.trim(),rating:Number($('#tripRating').value)||0,status:tripStatus});if(!existing)state.trips.push(t);countries.forEach(c=>{state.statuses[c]=tripStatus==='upcoming'?'going':'visited';if(!state.countryAddedAt[c])state.countryAddedAt[c]=new Date().toISOString();if(state.statuses[c]==='visited'){state.visitHistory=state.visitHistory.filter(x=>!sameCountry(x,c));state.visitHistory.push(c)}});for(const c of oldCountries){if(countries.some(x=>sameCountry(x,c)))continue;const other=state.trips.some(x=>x!==t&&tripCountries(x).some(y=>sameCountry(y,c)));if(!other&&state.statuses[c]==='going')delete state.statuses[c]}editingTripId=null;save();$('#tripDialog').close();toast(existing?'Trip updated ✓':'Trip created ✈')};
