function openVisitedFilters(){const dlg=$('#visitedFilterDialog');if(!dlg)return;const years=[...new Set(Object.keys(state.statuses).filter(c=>state.statuses[c]==='visited').flatMap(c=>countryVisitMonths(c).map(m=>m.slice(0,4))))].filter(Boolean).sort((a,b)=>b.localeCompare(a));const yearOptions=[['all','All years'],...years.map(y=>[y,y])];const sortValue=visitedSortOptions.some(x=>x[0]===state.visitedListPrefs?.sort)?state.visitedListPrefs.sort:'default';const yearValue=years.includes(state.visitedListPrefs?.year)?state.visitedListPrefs.year:'all';const ratingOptions=[['all','All ratings'],['5','5 stars'],['4','4 stars & up'],['3','3 stars & up'],['2','2 stars & up'],['1','1 star & up']];const ratingValue=ratingOptions.some(x=>x[0]===state.visitedListPrefs?.rating)?state.visitedListPrefs.rating:'all';renderPicker('visitedSortMenu','visitedSortTrigger','visitedSort',visitedSortOptions,sortValue);renderPicker('visitedYearMenu','visitedYearTrigger','visitedYear',yearOptions,yearValue);renderPicker('visitedRatingMenu','visitedRatingTrigger','visitedRating',ratingOptions,ratingValue);closePickerMenus();dlg.showModal()}
